// Synthetic test data only; used to compare all state except the protected goal title.
function openRecipeGoalQty(gid){const g=state.goals.find(x=>x.id===gid);if(!g?.sourceRecipeId)return;modal(`<h3>作る数を変更</h3><div class="field"><label>${esc(rname(g.sourceRecipeId))}</label><input id="editRecipeQty" type="number" min="1" value="${g.targetQty||1}" inputmode="numeric"></div><p class="small muted">自動生成した必要数を新しい作る数に合わせます。現在数は維持します。</p><div class="sheet-actions"><button class="btn secondary" id="cancelRecipeQty">キャンセル</button><button class="btn" id="saveRecipeQty">更新</button></div>`);$('#cancelRecipeQty').onclick=()=>returnToGoal(gid);$('#saveRecipeQty').onclick=async()=>{const qty=Math.max(1,+$('#editRecipeQty').value||1),old=Math.max(1,g.targetQty||1);g.targetQty=qty;g.title=`${rname(g.sourceRecipeId)} ×${qty}`;for(const req of state.requirements[gid]||[]){if(req.sourceRecipeId===g.sourceRecipeId){const unit=Math.max(1,Math.round(req.need/old));req.need=unit*qty;req.have=Math.min(req.have,req.need)}}await save();returnToGoal(gid);toast('作る数を更新しました')}}
